import pickle, numpy as np
from pathlib import Path

class Store:
    def __init__(self, path: str = "{{store_path}}"):
        self.path = Path(path)
        if self.path.exists():
            self.docs, self.vecs = pickle.loads(self.path.read_bytes())
        else:
            self.docs, self.vecs = [], np.zeros((0, 0))

    def add(self, doc: str, vec: np.ndarray):
        if self.vecs.size == 0:
            self.vecs = vec.reshape(1, -1)
        else:
            self.vecs = np.vstack([self.vecs, vec])
        self.docs.append(doc)

    def search(self, q: np.ndarray, k=5):
        sims = (self.vecs @ q).flatten()
        idx = np.argsort(-sims)[:k]
        return [(self.docs[i], float(sims[i])) for i in idx]

    def save(self):
        self.path.write_bytes(pickle.dumps((self.docs, self.vecs)))
